function paintRoute(){const chosen=state.drafts.p5?.route||[],last=chosen.at(-1)||'activity';$$('[data-route-node]').forEach(b=>{const key=b.dataset.routeNode,on=key==='activity'||chosen.includes(key),adjacent=edges.some(([a,c])=>(a===last&&c===key)||(c===last&&a===key));b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));b.disabled=key==='activity'||(chosen.includes(key)&&key!==last)||(!chosen.includes(key)&&!adjacent)});const slot=$('#puzzle-p5 .preview-slot');if(slot)slot.innerHTML=routePreview()}
